// Normalises the two shapes n8n uses for error payloads (execution errors vs trigger errors).
const e = $input.first().json;
const wf = e.workflow ?? {};
const exec = e.execution ?? {};
const trig = e.trigger ?? {};

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const message = exec.error?.message ?? trig.error?.message ?? 'Unknown error';
const node = exec.lastNodeExecuted ?? trig.error?.node?.name ?? 'n/a';
const mode = exec.mode ?? trig.mode ?? 'n/a';
const url = exec.url ?? '';
const stack = String(exec.error?.stack ?? '').split('\n').slice(0, 4).join('\n');

const lines = [
  `🚨 <b>n8n workflow failed</b>`,
  `📄 Workflow: <b>${esc(wf.name)}</b> (id ${esc(wf.id)})`,
  `🧩 Node: <code>${esc(node)}</code>`,
  `⚙️ Mode: ${esc(mode)}`,
  `🕒 ${new Date().toISOString()}`,
  ``,
  `❌ <b>Error</b>`,
  `<pre>${esc(message).slice(0, 800)}</pre>`,
];
if (stack) lines.push(`<pre>${esc(stack).slice(0, 600)}</pre>`);
if (url) lines.push(`🔗 <a href="${esc(url)}">Open execution</a>`);

return [{ json: { text: lines.join('\n'), workflowName: wf.name, node, message, url } }];
